/*
 * prog41_series_sum – reproduced from the supplied binary
 *
 * Behaviour (identical to the original):
 *
 *   * If fewer than two command‑line arguments are supplied:
 *         prints "NO_INPUT"
 *
 *   * The first argument (mode) and the second argument (n) are parsed
 *     with `strtol`.  Any parsing error (no digits, extra characters,
 *     overflow) results in "BAD_INPUT".
 *
 *   * The first argument must be 1, 2 or 3.  Any other value prints
 *     "BAD_MODE".
 *
 *   * The second argument must be a non‑negative integer not larger than
 *     100 000.  Values >100000 cause "OUT_OF_RANGE".
 *
 *   * For a valid (mode, n) pair the program computes a series sum and
 *     prints it with six digits after the decimal point:
 *
 *         mode == 1 :  Σ_{k=1..n} 1/(k*k)          (Basel series)
 *         mode == 2 :  Σ_{k=1..n} 1/k              (harmonic series)
 *         mode == 3 :  1 + Σ_{k=1..n} 1/k          (harmonic series + 1)
 *
 *   * The result is printed using `printf("%.6f\n", sum);`.
 *
 * All strings used by the original binary are reproduced exactly.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
       1. Argument count check
       ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
       2. Parse the first argument – the mode (must be 1, 2 or 3)
       ----------------------------------------------------------------- */
    char *endptr1;
    errno = 0;
    long mode = strtol(argv[1], &endptr1, 10);
    if (errno != 0 || *endptr1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
       3. Parse the second argument – the series length n
       ----------------------------------------------------------------- */
    char *endptr2;
    errno = 0;
    long n = strtol(argv[2], &endptr2, 10);
    if (errno != 0 || *endptr2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -----------------------------------------------------------------
       4. Dispatch based on the mode value
       ----------------------------------------------------------------- */
    double sum = 0.0;

    switch (mode) {
        case 1: {                     /* Σ 1/(k*k) */
            for (long k = 1; k <= n; ++k) {
                sum += 1.0 / ((double)k * (double)k);
            }
            break;
        }
        case 2: {                     /* Σ 1/k (harmonic) */
            for (long k = 1; k <= n; ++k) {
                sum += 1.0 / (double)k;
            }
            break;
        }
        case 3: {                     /* 1 + Σ 1/k */
            sum = 1.0;                /* the initial “1” added by the original */
            for (long k = 1; k <= n; ++k) {
                sum += 1.0 / (double)k;
            }
            break;
        }
        default:
            puts("BAD_MODE");
            return 0;
    }

    /* -----------------------------------------------------------------
       5. Output the result
       ----------------------------------------------------------------- */
    printf("%.6f\n", sum);
    return 0;
}
